import {repository as repo,stages} from './data.js';
const routes={control:'관제 요약',conflicts:'충돌 관제',deployments:'배포편',experiments:'실험노선',credits:'크레딧·기여'};let filter=null;const app=document.querySelector('#app'),dialog=document.querySelector('#detail');const badge=s=>`<span class="badge ${['충돌','보류','HOLD'].includes(s)?'warn':['작업 중','검표 중'].includes(s)?'neutral':''}">${s}</span>`;const btn=(text,action,id,primary=false)=>`<button ${primary?'class="primary"':''} data-action="${action}" data-id="${id}">${text}</button>`;
function rows(saves){return `<div class="panel stream"><div class="table-head"><span>세이브</span><span>크레딧 / 승객</span><span class="actor">주체</span><span>상태</span></div>${saves.length?saves.map(s=>`<button class="save-row" data-detail="${s.id}"><span class="id">${s.id}</span><span><b>${s.credit}</b><small>${s.id} · ${s.task.id} · 오늘 ${s.time}</small></span><span class="actor">${s.actor}</span>${badge(s.status)}</button>`).join(''):'<div class="empty">이 상태의 세이브가 없습니다.</div>'}</div>`}
function render(){let route=location.hash.slice(1)||'control';if(!routes[route])route='control';document.querySelector('nav').innerHTML=Object.entries(routes).map(([k,v],i)=>`<a href="#${k}" class="${k===route?'active':''}" ${k===route?'aria-current="page"':''}>${['▦','◇','▤','⑂','◎'][i]} &nbsp; ${v}</a>`).join('');document.querySelector('#breadcrumb').textContent=routes[route];const saves=repo.list(),conflicts=saves.filter(s=>s.conflict&&!s.conflict.resolved),boarding=saves.filter(s=>s.status==='배포 대기');let html=`<div class="eyebrow" style="margin-top:26px">손잡고 탑승 시스템</div><h1>${route==='control'?'개발을 대기열이 아니라 흐름으로.':routes[route]}</h1>`;
if(route==='control'){html+=`<p>문제없는 변경은 계속 흐르고, 충돌한 변경만 함께 조정합니다.</p><div class="metrics">${stages.map(s=>`<button class="metric" data-filter="${s}" aria-pressed="${filter===s}"><span>${s}</span><strong>${(s==='충돌'?conflicts.length:s==='작업 중'?new Set(saves.filter(x=>x.status===s).map(x=>x.task.id)).size:saves.filter(x=>x.status===s).length).toString().padStart(2,'0')}</strong><small>${s==='작업 중'?'승객 기준':'세이브 기준'}</small></button>`).join('')}</div><div class="grid"><section><div class="heading"><h2>${filter?filter+' 세이브':'최근 세이브'}</h2>${filter?'<button data-clear>전체 보기</button>':'<span class="count-label">시간순 체크포인트</span>'}</div>${rows(filter?saves.filter(s=>filter==='충돌'?s.conflict&&!s.conflict.resolved:s.status===filter):saves)}</section><section><div class="heading"><h2>관제에서 확인할 일</h2></div><div class="panel"><span class="eyebrow">충돌 ${conflicts.length}건</span><h3 style="margin-top:12px">작업판 정렬 기준 조정</h3><div class="notice">${conflicts[0]?.conflict.reason||'해결되지 않은 충돌이 없습니다.'}</div><a href="#conflicts">충돌 관제 열기</a></div><div class="panel" style="margin-top:18px"><span class="eyebrow">다음 배포편 #77</span><h3 style="margin-top:10px">${boarding.length}개 세이브 탑승</h3><div class="track"></div><p>검표 통과 → GitHub 통합 → 배포</p><a href="#deployments">배포편 보기</a></div></section></div>`}
if(route==='conflicts')html+=`<p>충돌한 세이브만 멈춥니다. 다른 세이브의 흐름은 계속됩니다.</p>${conflicts.length?conflicts.map(s=>`<section class="panel"><div class="heading"><h2>${s.id} · ${s.credit}</h2>${badge(s.status)}</div><h3>충돌 이유</h3><p>${s.conflict.reason}</p><h3>영향 범위</h3><p>${s.conflict.impact}</p><div class="notice"><b>AI 관제 제안</b><br>${s.conflict.proposal}</div><p>${s.conflict.orderAdjusted?'순서 조정됨: S-1850 → '+s.id+' · 코드 재적용과 재검표는 여전히 필요합니다.':'순서는 아직 조정되지 않았습니다.'}</p><div class="actions">${btn('재검표','recheck',s.id,true)}${btn(s.status==='보류'?'보류 재개':'보류',s.status==='보류'?'resume':'hold',s.id)}${btn('제안 순서 적용','order',s.id)}<button data-detail="${s.id}">세이브 상세</button></div></section>`).join(''):'<div class="panel">현재 충돌이 없습니다.</div>'}`;
if(route==='deployments')html+=`<p>배포편은 검표가 끝난 세이브를 묶습니다. 탑승과 실제 배포는 별도 단계입니다.</p><div class="cards"><section class="panel"><div class="heading"><h2>다음 배포편 #77</h2>${badge('배포 대기')}</div>${boarding.map(s=>`<div class="contribution"><button data-detail="${s.id}">${s.id} · ${s.credit}</button><p>GitHub: ${s.integration.status}</p>${btn('탑승 취소','unboard',s.id)}</div>`).join('')||'<p>아직 탑승한 세이브가 없습니다.</p>'}<div class="notice">체험용 배포편 · 실제 배포 요청은 연결 전입니다.</div></section><section class="panel"><h2>탑승 대기</h2>${saves.filter(s=>s.status!=='배포 대기').map(s=>`<div class="contribution"><b>${s.id} · ${s.credit}</b><div class="line">${badge(s.status)}</div>${s.status==='탑승 가능'?btn('다음 배포편 탑승','board',s.id,true):'<small>검표 통과 후 탑승할 수 있습니다.</small>'}</div>`).join('')}</section></div><div class="heading"><h2>배포 이력</h2></div><div class="panel">본선 #76 · 14:20 · 완료 <small>체험용 배포 이력 · S-1838, S-1839</small></div>`;
if(route==='experiments')html+=`<p>실험노선은 최신 본선 위에 실험 세이브를 겹쳐 봅니다.</p><section class="panel"><div class="heading"><h2>새 작업맵 · 실험노선</h2>${badge('HOLD')}</div><div class="branch-base"><b>최신 본선 #76</b><br><small>기준 버전 mock-main-76 · 마지막 동기화 14:20</small></div><div class="overlay"><h3>실험 세이브 겹쳐 보기</h3><p>E-41 · 작업 관계를 노선으로 표시</p><p>E-42 · 의미별 묶음 탐색</p></div><div class="notice"><b>HOLD · 본선 동기화 중단</b><br>작업맵 탑승권과 본선의 작업 관계 스키마가 충돌합니다. 실험 세이브는 보존됩니다.</div><div class="actions">${btn('동기화 재검표','sync','branch',true)}</div><p><small>충돌이 남아 있는 동안 기준 버전을 바꾸거나 본선에 승격하지 않습니다.</small></p></section>`;
if(route==='credits')html+=`<p>크레딧은 세이브포인트의 한 줄 제목입니다. 기여의 역할과 근거는 그 아래에 남습니다.</p><div class="panel">${saves.map(s=>`<div class="contribution"><button data-detail="${s.id}"><b>${s.id} · ${s.credit}</b></button><p>${s.contributors.map(c=>`${c.name} (${c.kind}) · ${c.role}`).join(' / ')}</p><small>실제 투입시간·기여 평가·분배는 연결되지 않았습니다.</small></div>`).join('')}</div>`;
app.innerHTML=html;}
function detail(id){const s=repo.get(id);document.querySelector('#detail-body').innerHTML=`<span class="eyebrow">시간순 체크포인트 · ${s.id}</span><h1>${s.credit}</h1>${badge(s.status)}<p>오늘 ${s.time} · ${s.actor}</p>${[['01 크레딧',s.credit],['02 승객 · 작업',`${s.task.id} · ${s.task.title}`],['03 탑승권 · 변경 파일',s.tickets.map(t=>`${t.path}<br>영향: ${t.scope}`).join('<br>')],['04 검증',`${s.verification.status}<br>${s.verification.evidence}`],['05 기여자·AI',s.contributors.map(c=>`${c.name} · ${c.kind} · ${c.role}`).join('<br>')],['06 GitHub 통합',`${s.integration.status}<br>${s.integration.ref}`],['07 배포 이력',s.status==='배포 대기'?'다음 배포편 #77에 탑승 · 실제 배포 전':'배포 이력 없음']].map(([title,body],i)=>`<details class="section" ${i===0?'open':''}><summary>${title}</summary><p>${body}</p></details>`).join('')}<div class="actions">${s.status==='탑승 가능'?btn('다음 배포편 탑승','board',s.id,true):''}</div>`;if(!dialog.open)dialog.showModal();}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',4500)}
document.addEventListener('click',e=>{const d=e.target.closest('[data-detail]');if(d){detail(d.dataset.detail);return}const f=e.target.closest('[data-filter]');if(f){filter=filter===f.dataset.filter?null:f.dataset.filter;render();return}if(e.target.closest('[data-clear]')){filter=null;render()}const b=e.target.closest('[data-action]');if(b){try{if(b.dataset.action==='sync')toast(repo.syncBranch());else{const s=repo.act(b.dataset.id,b.dataset.action);toast(b.dataset.action==='recheck'&&s.conflict&&!s.conflict.resolved?'재검표 완료 · 동일 충돌이 남아 있습니다.':b.dataset.action==='order'?'순서 조정 반영 · 충돌 해결은 아직 필요합니다.':'체험 상태가 반영되었습니다.');render();if(dialog.open)detail(s.id)}}catch(error){toast(error.message)}}});document.querySelector('.close').onclick=()=>dialog.close();document.querySelector('#reset').onclick=()=>{repo.reset();filter=null;dialog.close();render();toast('처음 체험 상태로 돌아왔습니다.')};window.addEventListener('hashchange',()=>{filter=null;render()});render();
